input.sparql:
SELECT ?name ?ts WHERE {
  ?p a brick:ElectricPower ; brick:hasTag ?name .
  FILTER (?name IN ("AHU01","AHU03","SupplyFan_AHU02"))
  ?p ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT ?uri ?class WHERE {
  ?p a brick:ElectricPower .
  OPTIONAL { ?p brick:hasTag ?t . BIND(STR(?t) AS ?tag) }
  ?p ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT DISTINCT ?class WHERE {
  ?p a ?class .
  FILTER (LCASE(STR(?class)) CONTAINS "power" || LCASE(STR(?class)) CONTAINS "electric" || LCASE(STR(?class)) CONTAINS "energ" || LCASE(STR(?class)) CONTAINS "energy" || LCASE(STR(?class)) CONTAINS "kwh" || LCASE(STR(?class)) CONTAINS "fan")
}

SELECT ?name WHERE {
  ?p brick:hasTag ?name .
  FILTER (LCASE(STR(?name)) CONTAINS "ahu" || LCASE(STR(?name)) CONTAINS "supplyfan")
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?name ?ts WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ref:hasExternalReference ?refn .
  ?refn ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point brick:isPointOf ?equip . BIND(str(?equip) AS ?name) }
  OPTIONAL { ?point rdfs:label ?lbl . BIND(str(?lbl) AS ?label) }
}

